export interface ContactDraft {
  readonly name: string;
  readonly email: string;
}

export interface ContactError {
  readonly field: "name" | "email";
  readonly code: "required" | "format";
}

export interface ContactValidation {
  readonly valid: boolean;
  readonly value: ContactDraft;
  readonly errors: readonly ContactError[];
}

export function validateContactDraft(input: ContactDraft): ContactValidation {
  const value: ContactDraft = { name: input.name.trim(), email: input.email.trim() };
  const errors: ContactError[] = [];
  if (value.name.length === 0) errors.push({ field: "name", code: "required" });
  if (value.email.length === 0) {
    errors.push({ field: "email", code: "required" });
  } else {
    const parts = value.email.split("@");
    const domain = parts[1] ?? "";
    const dot = domain.indexOf(".");
    const formatted = parts.length === 2 && parts[0].length > 0 && domain.length > 0 &&
      !/\s/.test(value.email) && dot > 0 && dot < domain.length;
    if (!formatted) errors.push({ field: "email", code: "format" });
  }
  return { valid: errors.length === 0, value, errors };
}
```

