import { validateContactDraft, type ContactDraft } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}

const input: ContactDraft = { name: "  Ada Lovelace  ", email: "  ada@example.org  " };
const valid = validateContactDraft(input);
equal(valid, {
  valid: true,
  value: { name: "Ada Lovelace", email: "ada@example.org" },
  errors: [],
}, "valid fields should be trimmed and accepted");
equal(input, { name: "  Ada Lovelace  ", email: "  ada@example.org  " }, "input must not be mutated");

const required = validateContactDraft({ name: " \t ", email: "  " });
equal(required, {
  valid: false,
  value: { name: "", email: "" },
  errors: [
    { field: "name", code: "required" },
    { field: "email", code: "required" },
  ],
}, "required errors should be reported in name-then-email order without a format error");

const malformed = [
  "plainaddress",
  "@example.com",
  "name@",
  "a@@example.com",
  "a b@example.com",
  "a@ example.com",
  "a@.example",
  "a@example.",
  "a@example",
];
for (const email of malformed) {
  equal(validateContactDraft({ name: "Name", email }), {
    valid: false,
    value: { name: "Name", email: email.trim() },
    errors: [{ field: "email", code: "format" }],
  }, "malformed nonempty email should receive exactly one format error: " + email);
}

equal(validateContactDraft({ name: "Name", email: "a@b.c" }).valid, true, "a dot inside a nonempty domain should be accepted");
const first = validateContactDraft(input);
const second = validateContactDraft(input);
assert(first !== second && first.value !== second.value && first.errors !== second.errors, "all returned containers should be fresh");

const invalidA = validateContactDraft({ name: "", email: "bad" });
const invalidB = validateContactDraft({ name: "", email: "bad" });
assert(invalidA.errors[0] !== invalidB.errors[0] && invalidA.errors[1] !== invalidB.errors[1], "returned error objects should be fresh");
(invalidA.value as { name: string }).name = "outside";
(invalidA.errors as ContactErrorLike[])[0].code = "format";
equal(invalidB, {
  valid: false,
  value: { name: "", email: "bad" },
  errors: [
    { field: "name", code: "required" },
    { field: "email", code: "format" },
  ],
}, "mutating one result must not affect another");

type ContactErrorLike = { field: "name" | "email"; code: "required" | "format" };

